{
  "arguments": [
    {
      "claim": "The artillery attacks on Knin, Benkovac, Obrovac and Gračac violated the proportionality rule of international humanitarian law and therefore constitute a war crime under Rome Statute article 8(2)(b)(iv).",
      "reasoning": "Rome Statute article 8(2)(b)(iv) prohibits \"Intentionally launching an attack in the knowledge that such attack will cause incidental loss of life or injury to civilians or damage to civilian objects ... which would be clearly excessive in relation to the concrete and direct overall military advantage anticipated\". The Trial Chamber found that impact sites were more than 200 metres from any legitimate military target and that the HV could not identify targets of opportunity in the towns. Given the dense civilian presence and the lack of verified military advantage, the attacks were disproportionate and thus unlawful under the cited provision.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Intentionally launching an attack in the knowledge that such attack will cause incidental loss of life or injury to civilians or damage to civilian objects or widespread, long-term and severe damage to the natural environment which would be clearly excessive in relation to the concrete and direct overall military advantage anticipated;"
        }
      ]
    },
    {
      "claim": "The artillery attacks intentionally struck civilian objects, namely residential areas in the four towns, constituting a war crime under Rome Statute article 8(2)(b)(ii).",
      "reasoning": "Rome Statute article 8(2)(b)(ii) defines a war crime as \"Intentionally directing attacks against civilian objects, that is, objects which are not military objectives\". The Chamber’s forensic analysis applied a 200‑metre margin of error and concluded that the majority of impact sites lay outside any verified military target, indicating that the shells hit civilian structures. The absence of identified military objectives in the towns demonstrates that the attacks were directed at civilian objects, satisfying the elements of article 8(2)(b)(ii).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Intentionally directing attacks against civilian objects, that is, objects which are not military objectives;"
        }
      ]
    },
    {
      "claim": "The use of artillery in densely populated towns breached the prohibition on attacks on military objectives located within a concentration of civilians under CCW Protocol III article 2(3), because feasible precautions to limit civilian harm were not taken.",
      "reasoning": "CCW Protocol III article 2(3) states: \"It is further prohibited to make any military objective located within a concentration of civilians the object of attack by means of incendiary weapons ... and all feasible precautions are taken with a view to limiting the incendiary effects to the military objective and to avoiding, and in any event to minimizing, incidental loss of civilian life, injury to civilians and damage to civilian objects.\" Although the weapons were artillery, the same principle of taking all feasible precautions applies to any attack on a target embedded in a civilian concentration. Expert testimony on wind speed, temperature and the 200‑metre error margin shows that the HV failed to take such precautions, rendering the attacks unlawful under the cited rule.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ccw_p_iii",
          "article": "2(3)",
          "quoted_text": "It is further prohibited to make any military objective located within a concentration of civilians the object of attack by means of incendiary weapons other than air-delivered incendiary weapons, except when such military objective is clearly separated from the concentration of civilians and all feasible precautions are taken with a view to limiting the incendiary effects to the military objective and to avoiding, and in any event to minimizing, incidental loss of civilian life, injury to civilians and damage to civilian objects."
